const charDefs=[
 ['franklin','Franklin Blake',[],'Rachel’s cosmopolitan cousin, whose determination to recover the truth eventually turns the inquiry upon his own missing memory.',47,true],
 ['rachel','Rachel Verinder',[],'A strong-willed heiress who protects the person she believes stole her birthday diamond even while refusing to excuse him.',37,true],
 ['betteredge','Gabriel Betteredge',[],'The Verinders’ loyal house-steward and first narrator, guided by habit, affection, and repeated consultation of Robinson Crusoe.',66,true],
 ['penelope','Penelope Betteredge',[],'Gabriel’s perceptive daughter and Rachel’s maid, often quicker than her father to understand emotional evidence.',23,true],
 ['rosanna','Rosanna Spearman',[],'A reformed thief working as a housemaid, isolated by shame and driven by unreturned devotion to protect Franklin.',10,false],
 ['lady-verinder','Lady Julia Verinder',[],'Rachel’s mother, an intelligent and protective widow who balances family dignity against the need for an honest inquiry.',35,false],
 ['cuff','Sergeant Cuff',[],'A patient detective whose attention to small material facts and human motives makes him formidable even when his first conclusion fails.',25,true],
 ['godfrey','Godfrey Ablewhite',[],'Rachel’s admired cousin and public philanthropist, whose reputation conceals debts and a decisive act of opportunism.',46,false],
 ['miss-clack','Drusilla Clack',[],'A fervent evangelical cousin whose intrusive charity and self-serving narration nonetheless preserve crucial conversations.',44,true],
 ['bruff','Matthew Bruff',[],'The Verinder family solicitor, bringing legal memory, financial records, and disciplined skepticism to the investigation.',51,true],
 ['candy','Doctor Candy',[],'The sociable Frizinghall physician whose offended professional pride leads him to administer opium without consent.',57,true],
 ['ezra','Ezra Jennings',[],'Candy’s marginalized assistant, a skilled and compassionate medical thinker who reconstructs Franklin’s forgotten actions.',65,false],
 ['luker','Septimus Luker',[],'A London money-lender who accepts the diamond as security and becomes a target of the Indian guardians.',41,true],
 ['murthwaite','Mr Murthwaite',[],'A widely travelled observer of India who recognizes the diamond’s religious significance and later witnesses its restoration.',20,true],
 ['lucy','Limping Lucy Yolland',[],'Rosanna’s fierce friend at Cobb’s Hole, entrusted with a letter and contemptuous of the household that failed her.',39,true],
 ['mrs-yolland','Mrs Yolland',[],'Lucy’s mother, whose cottage gives Rosanna privacy, practical help, and a place to arrange the hidden tin case.',29,true],
 ['seegrave','Superintendent Seegrave',[],'The local officer whose blunt search of the household spreads resentment and damages evidence.',24,true],
 ['gooseberry','Gooseberry',[],'A sharp street boy employed by Bruff and Cuff to follow suspects through London without attracting notice.',69,true],
 ['herncastle','Colonel John Herncastle',[],'The estranged uncle who violently takes the Moonstone at Seringapatam and leaves it to Rachel as a dangerous legacy.',2,false],
 ['guardian-one','First Indian Guardian',['The Chief Indian'],'One of three hereditary guardians who pursues the sacred diamond across England and coordinates its recovery.',3,true],
 ['guardian-two','Second Indian Guardian',[],'A disguised Brahmin maintaining surveillance of the stone and its temporary holders.',8,true],
 ['guardian-three','Third Indian Guardian',[],'The third member of the watch, sharing exile and ritual obligation until the Moonstone returns to its shrine.',20,true],
 ['dying-guardian','Guardian in the Armoury',[],'The mortally wounded custodian who identifies Herncastle’s theft and warns that the sacred stone will be avenged.',2,false],
 ['ablewhite-sr','Mr Ablewhite',[],'Godfrey’s wealthy father, determined to defend the family name until financial evidence defeats denial.',51,true],
 ['narrator','Herncastle’s Cousin',[],'The unnamed officer whose family paper records the theft at Seringapatam and refuses fellowship with Herncastle.',1,true],
 ['cuffs-man','Sergeant Cuff’s Agent',[],'The investigator sent to trace the three guardians from London through Gravesend and Plymouth.',71,true],
 ['ship-captain','Captain of the Bewley Castle',[],'The East Indiaman’s captain whose statement explains how the guardians left the becalmed ship near India.',71,true],
]
